package main

import (
	"encoding/hex"
	"fmt"
	"log"
	"os"
	"strings"
	"time"

	"github.com/alecthomas/kingpin/v2"
	"github.com/gocql/gocql"
)

var (
	clusterHosts   = kingpin.Arg("hosts", "Scylla nodes IP addresses, comma separated (i.e. 192.168.1.1,192.168.1.2)").Required().String()
	keyspace       = kingpin.Flag("keyspace", "Keyspace to use").Short('k').Default("clio_fh").String()
	userName       = kingpin.Flag("username", "Username to use when connecting to the cluster").String()
	password       = kingpin.Flag("password", "Password to use when connecting to the cluster").String()
	clusterTimeout = kingpin.Flag("timeout", "Maximum duration for query execution in millisecond").Short('t').Default("90000").Int()
)

// TransactionData holds the data for a single transaction record.
type TransactionData struct {
	Hash        string
	Metadata    string
	Transaction string
}

// LedgerDataBatch holds all the transactions for a specific ledger sequence.
type LedgerDataBatch struct {
	LedgerSequence uint64
	Date           int32
	Transactions   []TransactionData
}

// allBatches contains all the data to be inserted
var allBatches = []LedgerDataBatch{
	{
		LedgerSequence: 7266393,
		Date:           456420950,
		Transactions: []TransactionData{
			{Hash: "DBA2CDE916A8BF8993CFE13C2497185066B7A07A73233355BAE1F6CFD3822062", Metadata: "", Transaction: ""},
			{Hash: "DC766E8D357CC5AC2DC231F7C65AFAE99D6283ADEC68B3A30D9122CD5C2BFA3C", Metadata: "", Transaction: ""},
			{Hash: "E22EB4AE8D00A5C10512A56049EDC49FDBC2E7431C853669C1948B01132C0837", Metadata: "", Transaction: ""},
			{Hash: "EA2D0F6D499B36CBAA6A4C6CC7DEF8865DFC19FF0909A7DA4F39B6A00C71F9F3", Metadata: "", Transaction: ""},
		},
	},
	{
		LedgerSequence: 7266396,
		Date:           456420960,
		Transactions: []TransactionData{
			{Hash: "E087B2D2DEB27337C57B8132513A779F391F4244F30BFB8EA625948A6A2147F2", Metadata: "", Transaction: ""},
			{Hash: "E171DEC6015FA0D8EFA4DB7774C0B9CAC49DE0E1330CC5F8F88488443ED34252", Metadata: "", Transaction: ""},
			{Hash: "FA826AD72A4C09D6E938D45CF9860F2C33519E6D168F38F17AE9BE046829E9C3", Metadata: "", Transaction: ""},
		},
	},
}

func insertLedgerWithTransaction(session *gocql.Session, ledgerSeq uint64, txHashHex string) error {
	txHashBytes, err := hex.DecodeString(txHashHex)
	if err != nil {
		return fmt.Errorf("failed to decode transaction hash '%s': %w", txHashHex, err)
	}

	log.Printf("Attempting to insert new row into 'ledger_transactions' table for ledger %d...", ledgerSeq)

	query := `INSERT INTO ledger_transactions (ledger_sequence, hash) VALUES (?, ?)`
	if err := session.Query(query, ledgerSeq, txHashBytes).Exec(); err != nil {
		return fmt.Errorf("failed to execute insert for 'ledger_transactions' table on ledger %d: %w", ledgerSeq, err)
	}
	log.Printf("Successfully inserted row into 'ledger_transactions' table for ledger %d.", ledgerSeq)
	return nil
}

func insertTransactionRow(session *gocql.Session, ledgerSeq uint64, date int32, txData TransactionData) error {
	hashBytes, err := hex.DecodeString(txData.Hash)
	if err != nil {
		return fmt.Errorf("failed to decode hash: %w", err)
	}
	metadataBytes, err := hex.DecodeString(txData.Metadata)
	if err != nil {
		return fmt.Errorf("failed to decode metadata: %w", err)
	}
	transactionBytes, err := hex.DecodeString(txData.Transaction)
	if err != nil {
		return fmt.Errorf("failed to decode transaction: %w", err)
	}

	log.Printf("Attempting to insert row into 'transactions' table for ledger %d...", ledgerSeq)

	query := `INSERT INTO transactions (hash, date, ledger_sequence, metadata, transaction) VALUES (?, ?, ?, ?, ?)`
	if err := session.Query(query, hashBytes, date, ledgerSeq, metadataBytes, transactionBytes).Exec(); err != nil {
		return fmt.Errorf("failed to execute insert for 'transactions' table on ledger %d: %w", ledgerSeq, err)
	}

	log.Printf("Successfully inserted row into 'transactions' table for ledger %d.", ledgerSeq)
	return nil
}

func main() {
	log.SetOutput(os.Stdout)
	log.SetFlags(log.LstdFlags | log.Lshortfile)
	kingpin.Parse()

	hosts := strings.Split(*clusterHosts, ",")
	cluster := gocql.NewCluster(hosts...)
	cluster.Timeout = time.Duration(*clusterTimeout * 1000 * 1000)
	cluster.NumConns = 1
	cluster.Keyspace = *keyspace

	if *userName != "" {
		cluster.Authenticator = gocql.PasswordAuthenticator{
			Username: *userName,
			Password: *password,
		}
	}

	session, err := cluster.CreateSession()
	if err != nil {
		log.Fatalf("Could not connect to database: %v", err)
	}
	defer session.Close()

	log.Println("Database session created successfully.")

	// --- Loop through each batch of ledgers ---
	for _, batch := range allBatches {
		log.Printf("--- Processing Batch for Ledger %d ---", batch.LedgerSequence)

		// --- Loop through each transaction in the batch and insert it ---
		for i, tx := range batch.Transactions {
			log.Printf("--- Processing record %d of %d (hash: %s...) ---", i+1, len(batch.Transactions), tx.Hash[:10])

			// Insert the ledger_transactions row
			if err := insertLedgerWithTransaction(session, batch.LedgerSequence, tx.Hash); err != nil {
				log.Fatalf("Failed to insert ledger_transactions row for hash %s: %v", tx.Hash, err)
			}

			// Insert the full transactions row
			if err := insertTransactionRow(session, batch.LedgerSequence, batch.Date, tx); err != nil {
				log.Fatalf("Failed to insert transactions row for hash %s: %v", tx.Hash, err)
			}
		}
	}

	log.Println("All operations completed successfully.")
}
